  ('pt-BR', 'whatsNew.item.codePanel.title', $json$"O painel Ao vivo virou Código, com os repositórios"$json$::jsonb),
  ('en', 'whatsNew.item.codePanel.title', $json$"The Live panel became Code, with the repositories"$json$::jsonb),
